## The problem

```js
getUser(userId, function(err, user) {
  if (err) return handleError(err);
  getOrders(user.id, function(err, orders) {
    if (err) return handleError(err);
    getInvoice(orders[0].id, function(err, invoice) {
      if (err) return handleError(err);
      sendEmail(user.email, invoice, function(err) {
        if (err) return handleError(err);
        console.log('Done!'); // ← buried 4 levels deep
      });
    });
  });
});
```

Problems: deep nesting; error handling repeated at every level; hard to add branching or retry logic; impossible to break out with `return`.

## Fix 1 — named functions (shallow fix)

```js
function onUser(err, user) {
  if (err) return handleError(err);
  getOrders(user.id, onOrders);
}
getUser(userId, onUser);
```

## Fix 2 — Promises

```js
getUser(userId)
  .then(user  => getOrders(user.id))
  .then(orders => getInvoice(orders[0].id))
  .then(invoice => sendEmail(userEmail, invoice))
  .catch(handleError);
```

## Fix 3 — async/await (modern standard)

```js
async function processOrder(userId) {
  try {
    const user    = await getUser(userId);
    const orders  = await getOrders(user.id);
    const invoice = await getInvoice(orders[0].id);
    await sendEmail(user.email, invoice);
    console.log('Done!');
  } catch (err) {
    handleError(err);
  }
}
```

Linear, readable, single error handler — the preferred pattern.

