## Uniqueness guarantee

```js
const id1 = Symbol('id');
const id2 = Symbol('id');

console.log(id1 === id2); // false — always unique
console.log(id1.toString()); // 'Symbol(id)'
console.log(typeof id1);     // 'symbol'
```

## Use case 1 — unique object keys

```js
const _private = Symbol('private');

const obj = {
  name: 'public',
  [_private]: 'hidden',
};

console.log(obj.name);       // 'public'
console.log(obj[_private]);  // 'hidden'
console.log(Object.keys(obj)); // ['name'] — Symbol key hidden
```

## Use case 2 — well-known Symbols (protocols)

```js
// Make your object iterable with for...of:
const range = {
  from: 1, to: 5,
  [Symbol.iterator]() {
    let current = this.from;
    const last  = this.to;
    return {
      next() {
        return current <= last
          ? { value: current++, done: false }
          : { value: undefined, done: true };
      },
    };
  },
};

for (const n of range) console.log(n); // 1 2 3 4 5
```

## Global registry

```js
// Symbol.for() creates/reuses a global symbol by key:
const s1 = Symbol.for('app.id');
const s2 = Symbol.for('app.id');
console.log(s1 === s2); // true — same global symbol
```

