## Basic generator

```js
function* counter(start = 0) {
  while (true) {
    yield start++;
  }
}

const gen = counter(1);
gen.next(); // { value: 1, done: false }
gen.next(); // { value: 2, done: false }
gen.next(); // { value: 3, done: false }
// Infinite, but only computes the next value on demand
```

## Finite generator

```js
function* range(from, to) {
  for (let i = from; i <= to; i++) yield i;
}

const nums = [...range(1, 5)]; // [1, 2, 3, 4, 5]
for (const n of range(1, 3)) console.log(n); // 1 2 3
```

## Two-way communication

```js
function* adder() {
  let sum = 0;
  while (true) {
    const n = yield sum; // yield sends sum out; next(n) sends n back in
    sum += n;
  }
}

const gen = adder();
gen.next();    // { value: 0, done: false } — initialise
gen.next(10);  // { value: 10, done: false }
gen.next(5);   // { value: 15, done: false }
```

## Custom iterable

```js
class NumberRange {
  constructor(start, end) { this.start = start; this.end = end; }

  *[Symbol.iterator]() {
    for (let i = this.start; i <= this.end; i++) yield i;
  }
}

[...new NumberRange(1, 4)]; // [1, 2, 3, 4]
```

