## The collision risk

```js
// You add this in 2020:
Array.prototype.flatten = function() { return this.flat(); };

// ES2019 already ships Array.prototype.flat() — close enough
// But what if a spec method named 'flatten' is added later with
// different behaviour? Your version silently wins.
```

## The enumeration problem

```js
Array.prototype.sum = function() {
  return this.reduce((a, n) => a + n, 0);
};

const arr = [1, 2, 3];
for (const key in arr) {
  console.log(key); // '0', '1', '2', 'sum' ← unexpected
}
```

## Library conflicts

```js
// Your code:
String.prototype.trim = function() { /* custom */ };

// Library loads next:
String.prototype.trim = function() { /* their custom */ };
// One silently overwrites the other — both may break
```

## Safe alternatives

```js
// Standalone utility function — no prototype mutation:
function sumArray(arr) {
  return arr.reduce((a, n) => a + n, 0);
}

// Subclass — extend, don't mutate:
class SmartArray extends Array {
  sum() { return this.reduce((a, n) => a + n, 0); }
}

// Polyfill — only when implementing the EXACT spec:
if (!Array.prototype.at) {
  Object.defineProperty(Array.prototype, 'at', {
    value: function(i) { /* spec-compliant */ },
    enumerable: false, // important — hides from for...in
  });
}
```

