## 1 — Lazy / infinite sequences

```js
// Generate IDs on demand — never runs out of memory:
function* idGenerator(prefix = 'id') {
  let n = 1;
  while (true) yield `${prefix}-${n++}`;
}

const gen = idGenerator('user');
gen.next().value; // 'user-1'
gen.next().value; // 'user-2'
```

## 2 — Custom iterables

```js
function* fibonacci() {
  let [a, b] = [0, 1];
  while (true) { yield a; [a, b] = [b, a + b]; }
}

// Take first 8 Fibonacci numbers:
const gen = fibonacci();
const first8 = Array.from({ length: 8 }, () => gen.next().value);
// [0, 1, 1, 2, 3, 5, 8, 13]
```

## 3 — redux-saga style orchestration

```js
function* fetchUserSaga(action) {
  const user = yield call(api.getUser, action.payload);
  yield put(userLoaded(user));
}
// yield produces plain descriptions — the middleware runs the actual I/O
```

## 4 — Lazy tree traversal

```js
function* walkTree(node) {
  yield node.value;
  for (const child of node.children) yield* walkTree(child);
}

// Process one node at a time, stopping whenever you want:
const walker = walkTree(root);
const first = walker.next().value;
```

## When NOT to use generators

- Sequential async API calls → use `async/await`
- Simple array transformations → use `map/filter/reduce`
- One-time iteration over a known array → `for...of`

