## Basic closure

```js
function makeCounter(initial = 0) {
  let count = initial; // 'count' is enclosed

  return {
    increment() { count++; },
    decrement() { count--; },
    value()     { return count; },
  };
}

const c = makeCounter(10);
c.increment(); c.increment();
c.value(); // 12 — 'count' persists between calls
```

## Private state without classes

```js
function createUser(name) {
  let loginCount = 0; // private — not accessible from outside

  return {
    login()    { loginCount++; },
    getCount() { return loginCount; },
    name,      // public
  };
}

const user = createUser('Aaron');
user.login();
user.getCount();  // 1
user.loginCount;  // undefined — truly private
```

## Memoization

```js
function memoize(fn) {
  const cache = new Map(); // enclosed in the returned function
  return (...args) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const result = fn(...args);
    cache.set(key, result);
    return result;
  };
}

const slowFib = n => n <= 1 ? n : slowFib(n-1) + slowFib(n-2);
const fastFib = memoize(slowFib);
```

## The classic loop bug (and fix)

```js
// Bug — var is shared across all iterations:
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 100); // 3 3 3
}

// Fix 1 — let creates a fresh binding per iteration:
for (let i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 100); // 0 1 2
}

// Fix 2 — IIFE closure (pre-ES6 pattern):
for (var i = 0; i < 3; i++) {
  ((j) => setTimeout(() => console.log(j), 100))(i);
}
```

